We assume that there exist computable constants $C_\infty>0$ and $M_\infty(\rho)\ge0$ such that
\begin{align*}
\|v\|_{L^\infty(\Omega)}\leq C_\infty\|v\|_V \quad \forall v\in V,
\quad
\|w\|_{L^\infty(\Omega)}\leq M_\infty(\rho)\quad \forall w\in B_{\rho}.
\end{align*}

Then, the element residual is
\begin{align*}
R_T^{\ast}(\sigma_h^{\ast})
:= s_h^{\ast} - \div\sigma_h^{\ast}\quad \text{in }T,
\end{align*}
and Theorem~\ref{thm:res-majorant} yields the guaranteed bound
\begin{align*}
\displaystyle
\|\mathcal G(z_h)\|_{V^\ast}
\leq \|\sigma_h^{\ast}-A\nabla z_h\|_{A_0^{-1}}
+
\alpha_0^{- \frac{1}{2}}\left(\sum_{T \in \mathbb T_h} \left( \frac{h_T}{\pi} \right)^2 
\|R_T^{\ast}(\sigma_h^{\ast})\|_{L^2(T)}^2 \right)^{\frac{1}{2}}.
\end{align*}
